export type JournalLanguageCode = 'en' | 'ja' | 'zh-HK' | 'zh-TW';
export type JournalLanguage = { code: JournalLanguageCode; segment: string; market: string; label: string; hreflang: string; ogLocale: string; siteLang: string };
export type JournalStatus = 'draft' | 'in_review' | 'approved' | 'scheduled' | 'published' | 'failed' | 'archived';
export type JournalSource = { label: string; url: string };
export type JournalReview = { facts?: boolean; claims?: boolean; images?: boolean; notes?: string; reviewer?: string; reviewed_at?: string };
export type JournalArticle = {
  id: string; group_key?: string | null; content_id?: string | null; language: JournalLanguageCode; market: string; slug: string;
  title: string; dek: string; body_md: string; hero_image_url?: string | null; hero_image_alt?: string | null; hero_image_caption?: string | null; hero_image_credit?: string | null;
  image_rights: 'confirmed' | 'pending' | 'restricted'; related_products: string[]; cta_type: 'product' | 'contact' | 'partners';
  seo_title?: string | null; seo_description?: string | null; sources: JournalSource[]; source_doc?: string | null;
  author_type: 'hondit_editorial' | 'ai_assisted' | 'partner_supplied'; author_name?: string; ai_meta?: Record<string, unknown> | null; review?: JournalReview;
  status: JournalStatus; approved_by?: string | null; approved_at?: string | null; publish_at?: string | null; published_at?: string | null; public_url?: string | null;
  publish_attempts?: number; last_error?: string | null; created_at?: string; updated_at?: string; previewOnly?: boolean;
};
export type JournalBlock = { type: 'p' | 'h2' | 'h3' | 'quote'; text: string } | { type: 'list'; items: string[] } | { type: 'image'; alt: string; src: string; caption: string };
export type ReviewResult = { ok: boolean; errors: string[]; warnings: string[]; checks: { facts: boolean; claims: boolean; images: boolean }; length: number };
export const SITE: string;
export const TIMEZONE: string;
export const JOURNAL_LANGUAGES: JournalLanguage[];
export function languageByCode(code: string | null | undefined): JournalLanguage | null;
export function languageBySegment(segment: string | null | undefined): JournalLanguage | null;
export const STATUSES: JournalStatus[];
export const PRODUCT_SLUGS: string[];
export const TRANSITIONS: Record<string, { from: JournalStatus[]; to: JournalStatus }>;
export function slugOk(slug: string): boolean;
export function articlePath(article: Pick<JournalArticle, 'language' | 'slug'>): string;
export function articleUrl(article: Pick<JournalArticle, 'language' | 'slug'>): string;
export function kstToUtc(value: string): string | null;
export function utcToKstInput(iso: string | null | undefined): string;
export function formatKst(iso: string | null | undefined): string;
export function formatDate(iso: string | null | undefined, language?: string): string;
export function parseBody(text: string): JournalBlock[];
export function inlineSegments(text: string): { text: string; href?: string }[];
export function marketLink(path: string, language: string | null | undefined): string;
export function reviewArticle(article: Partial<JournalArticle>, options?: { others?: Partial<JournalArticle>[]; publishing?: boolean }): ReviewResult;
export function isPublic(article: Partial<JournalArticle> | null | undefined, now?: Date | string): boolean;
export function isDue(article: Partial<JournalArticle> | null | undefined, now?: Date | string): boolean;
export function publicView<T extends Partial<JournalArticle>>(article: T): T;
export const ISSUED_LINK_IDS: string[];
export function nextLinkId(ids: string[]): string;
export function pressLink(row: { market: string; outlet: string; content_id?: string | null }, linkId: string, now?: Date): { url: string; campaign: string; linksRow: string[] };
export function withFinalUrl(body: string, url: string): string;
export const CHANNELS: Record<string, { label: string; source: string; medium: string; titleMax: number; bodyMax: number; link: boolean }>;
export const PIPELINE_COLUMNS: string[];
